ZRef<CItemInfo::LevelInfo> *__thiscall CItemInfo::GetLevelInfo(
        CItemInfo *this,
        ZRef<CItemInfo::LevelInfo> *result,
        int nItemID,
        int nLevel)
{
  const CItemInfo::EQUIPITEM *EquipItem; // ebx

  if ( CItemInfo::IsGrowthItem(this, nItemID) )
  {
    EquipItem = CItemInfo::GetEquipItem(this, nItemID);
    if ( EquipItem )
    {
      if ( nLevel <= 0 || nLevel > (int)CItemInfo::GetMaxLevel(this, nItemID) )
      {
        result->p = nullptr;
        return result;
      }
      else
      {
        ZRef<CItemInfo::LevelInfo>::ZRef<CItemInfo::LevelInfo>(result, &EquipItem->apLevelInfo.a[nLevel - 1]);
        return result;
      }
    }
    else
    {
      result->p = nullptr;
      return result;
    }
  }
  else
  {
    result->p = nullptr;
    return result;
  }
}
